import {
  Component,
  ComponentInterface,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Prop,
  State,
  Watch,
} from '@stencil/core';
import { fromEvent, Subject, takeUntil } from 'rxjs';
import { IconOnlyToggleMode, NavigationSizes } from '../../../../types';
import { AriaAttributes, extractAriaAttributes } from '../../../../utils/a11y-helper';
import { createMenuObserver, handleActiveMenuAttributes } from '../../../../utils/menu-helper';
import { NavigationUtilities } from '../shared/navigation-utilities';

type LocalSideNavigationItemElement =
  | HTMLGroupuiLocalSideNavigationItemElement
  | HTMLGroupuiLocalSideNavigationCategoryElement;

/**
 * @slot default - default slot for groupui-local-side-navigation-items
 * @slot collapse-label - slot for the content of the collapse button
 */
@Component({
  tag: 'groupui-local-side-navigation',
  styleUrl: 'local-side-navigation.scss',
  shadow: true,
})
export class LocalSideNavigation implements ComponentInterface {
  /**
   * sets the side-navigation size
   */
  @Prop({ reflect: true }) readonly size: NavigationSizes = 's';

  /**
   * activates the dividers
   */
  @Prop({ reflect: true }) readonly divider: boolean;

  /**
   * moves the chevrons to the left side
   */
  @Prop({ reflect: true }) readonly treeLayout: boolean;

  /**
   * Deactivates the active state management.
   */
  @Prop({ reflect: true }) readonly manualMode: boolean = false;

  /**
   * Activates the icon-only view (rail navigation).
   * Caution: Only Navigation items with an icon are displayed.
   * Categories, drill-downs and second-level items are also hidden.
   */
  @Prop({ reflect: true, mutable: true }) iconOnly: boolean;

  /**
   * Expands or collapses the navigation either on click, or on hover
   */
  @Prop({ reflect: true }) readonly iconOnlyToggleMode?: IconOnlyToggleMode;

  /**
   * Emitted when the component has loaded.
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  /**
   * Emitted when the active item changes
   */
  @Event({ bubbles: false }) groupuiChange: EventEmitter<void>;

  @State() private isNextToGlobalTop: boolean;
  @State() private isNextToLocalTop: boolean;
  @State() private isNextToLargeLocalTop: boolean;
  @State() hovering: boolean = false;
  @Element() host: HTMLElement;

  private ariaAttributes: AriaAttributes;

  private menuObserver: MutationObserver;
  private destroy: Subject<void>;

  private navigationUtilities = new NavigationUtilities<LocalSideNavigationItemElement>();

  private delayBeforeCloseOnHover = 160;
  private delayBeforeOpenOnHover = 480;
  private timeout: NodeJS.Timeout;

  @Watch('size')
  updateSizePropOfChild() {
    const items = [
      ...this.navigationUtilities.getAllItems(
        this.host,
        'groupui-local-side-navigation-item, groupui-local-side-navigation-category, groupui-local-side-navigation-drilldown-item'
      ),
    ];
    this.navigationUtilities.setAttribute(items, 'size', this.size);
  }

  @Watch('divider')
  updateDividerPropOfChild() {
    const items = this.navigationUtilities.getAllItems(
      this.host,
      'groupui-local-side-navigation-item, groupui-local-side-navigation-drilldown-item'
    );
    this.navigationUtilities.updateBooleanAttribute(items, 'divider', this.divider);
  }

  @Watch('treeLayout')
  updateTreeLayoutPropOfChild() {
    const items = this.navigationUtilities.getAllItems(this.host, 'groupui-local-side-navigation-item');
    this.navigationUtilities.updateBooleanAttribute(items, 'tree-layout', this.treeLayout);
  }

  @Watch('iconOnly')
  updateIconOnlyPropOfChild() {
    const items = this.navigationUtilities.getAllItems(
      this.host,
      [
        'groupui-local-side-navigation-item',
        'groupui-local-side-navigation-category',
        'groupui-local-side-navigation-drilldown-item',
      ].join(', ')
    );
    this.navigationUtilities.updateBooleanAttribute(items, 'icon-only', this.iconOnly);
  }

  @Watch('hovering')
  handleHoverChange(newValue: boolean) {
    clearTimeout(this.timeout);
    this.toggleAfterTimeout(newValue);
  }

  componentWillLoad(): void {
    this.ariaAttributes = extractAriaAttributes(this.host);
    this.updateSizePropOfChild();
    this.updateDividerPropOfChild();
    this.updateTreeLayoutPropOfChild();
    this.updateIconOnlyPropOfChild();
    this.checkForActiveChildItems();
    this.addMenuStyling();
    this.menuObserver = createMenuObserver();

    this.isNextToGlobalTop = document.querySelector('groupui-global-top-navigation') !== null;
    const localTop = document.querySelector('groupui-local-top-navigation');
    const localSide = document.querySelector('groupui-local-side-navigation');

    if (localTop && localSide) {
      this.isNextToLocalTop = localTop.compareDocumentPosition(localSide) === Node.DOCUMENT_POSITION_FOLLOWING;
    }

    if (this.isNextToLocalTop) {
      this.isNextToLargeLocalTop = localTop.size === 'l';
    }

    if (this.iconOnly) {
      this.host.setAttribute('icon-only', '');
    } else {
      this.host.removeAttribute('icon-only');
    }
  }

  connectedCallback() {
    this.destroy = new Subject<void>();
    this.listenToClickEvents();
  }

  private listenToClickEvents() {
    fromEvent(this.host, 'click')
      .pipe(takeUntil(this.destroy))
      .subscribe((event: MouseEvent) => {
        const item = (event.target as HTMLElement).closest('groupui-local-side-navigation-item');

        if (!item || item.disabled) {
          return;
        }

        if (this.isInsideMenu(item)) {
          return;
        }

        if (!this.manualMode) {
          if (this.isLeafItem(item) || this.iconOnly) {
            this.navigationUtilities.removeActiveFromAllItems(this.host, 'groupui-local-side-navigation-item');
            this.navigationUtilities.setActiveItem(item);
            this.groupuiChange.emit();
            this.host.dispatchEvent(new globalThis.Event('change'));
            return;
          }

          if (this.navigationUtilities.hasActiveChildItems(item, 'groupui-local-side-navigation-item')) {
            item.hasAttribute('open')
              ? this.navigationUtilities.setActiveItem(item)
              : this.navigationUtilities.removeActiveItem(item);
          }
        }
        this.navigationUtilities.toggleOpenState(item);
      });
  }

  componentDidLoad() {
    handleActiveMenuAttributes(this.host, this.menuObserver);
    this.groupuiDidLoad.emit();
  }

  disconnectedCallback() {
    this.destroy.next();
    this.destroy.complete();
    this.menuObserver?.disconnect();
  }

  private addMenuStyling() {
    this.host.querySelectorAll('groupui-menu').forEach((menu) => {
      menu.setAttribute('placement', 'right-start');
    });
  }

  private isLeafItem(element: HTMLGroupuiLocalSideNavigationItemElement): boolean {
    return element.querySelectorAll('groupui-local-side-navigation-item').length === 0;
  }

  private checkForActiveChildItems() {
    this.navigationUtilities
      .getAllItems(
        this.host,
        'groupui-local-side-navigation-item, groupui-local-side-navigation-category, groupui-local-side-navigation-drilldown-item'
      )
      .forEach((item) => {
        if (this.navigationUtilities.hasActiveChildItems(item, 'groupui-local-side-navigation-item')) {
          item.hasAttribute('open')
            ? this.navigationUtilities.removeActiveItem(item)
            : this.navigationUtilities.setActiveItem(item);
        }
      });
  }

  private isInsideMenu(item: Element) {
    return item.closest('groupui-menu') !== null;
  }

  private toggle = () => {
    this.iconOnly = !this.iconOnly;
  };

  private getExpandButton() {
    if (this.iconOnlyToggleMode !== 'on-click') return;

    return (
      <button id="expand" type="button" onClick={this.toggle}>
        <div>
          {!this.iconOnly && <slot name="collapse-label"></slot>}
          <groupui-icon
            aria-hidden="true"
            name={this.iconOnly ? 'chevron-double-right-24' : 'chevron-double-left-24'}
          ></groupui-icon>
        </div>
      </button>
    );
  }

  private toggleAfterTimeout(newValue: boolean) {
    this.timeout = setTimeout(
      () => {
        this.iconOnly = !newValue;
      },
      newValue ? this.delayBeforeOpenOnHover : this.delayBeforeCloseOnHover
    );
  }

  private addExpandOnHoverListener() {
    return this.iconOnlyToggleMode === 'on-hover'
      ? {
          onMouseEnter: () => (this.hovering = true),
          onMouseLeave: () => (this.hovering = false),
        }
      : {};
  }

  render() {
    return (
      <Host {...this.addExpandOnHoverListener()}>
        <nav
          {...this.ariaAttributes}
          class={{
            'global-top': this.isNextToGlobalTop,
            'local-top': this.isNextToLocalTop,
            'local-top-large': this.isNextToLargeLocalTop,
          }}
        >
          <slot name="nav-items"></slot>
          {this.getExpandButton()}
        </nav>
      </Host>
    );
  }
}
